import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

# Build lookup: {(project_basename, framework, package_id): version}
def build_lookup(data):
    lookup = {}
    for proj in data.get('projects', []):
        pname = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                lookup[(pname, tfm, pkg['id'])] = pkg['resolvedVersion']
    return lookup

b = build_lookup(baseline)
a = build_lookup(after)

all_keys = sorted(set(b.keys()) | set(a.keys()))
changes = []
unchanged = []
for k in all_keys:
    bv = b.get(k)
    av = a.get(k)
    if bv != av:
        changes.append((k[0], k[2], k[1], bv or 'N/A', av or 'N/A'))
    else:
        unchanged.append((k[0], k[2], k[1], bv))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'{c[0]} | {c[1]} ({c[2]}) | {c[3]} -> {c[4]}')
else:
    print('None')

print()
print('=== UNCHANGED ===')
for u in unchanged:
    print(f'{u[0]} | {u[1]} ({u[2]}) | {u[3]}')
"

